function LocalizedContact({ locale }: { locale: Locale }) { const page = copy[locale].pages.contact; const phone = business.phone.value ?? ""; const email = business.email.value ?? ""; const text = locale === "es" ? { contact: "Contacta a Revival", title: "Te ayudaremos a planificar el siguiente paso.", address: "Dirección postal", help: "Asistencia directa", helpTitle: "Habla con el equipo de Revival.", helpText: "Para obtener una respuesta más rápida, contacta directamente a Revival con la recogida, destino, fecha y detalles de pasajeros.", call: "Llama a Revival", email: "Escribe a Revival", note: "Los formularios en línea estarán disponibles cuando se conecte un servicio de entrega verificado.", instagram: "Instagram oficial" } : { contact: "Fale com a Revival", title: "Ajudaremos você a planejar o próximo passo.", address: "Endereço postal", help: "Atendimento direto", helpTitle: "Fale com a equipe da Revival.", helpText: "Para uma resposta mais rápida, entre em contato diretamente com a Revival e informe partida, destino, data e detalhes dos passageiros.", call: "Ligue para a Revival", email: "Envie um e-mail para a Revival", note: "Formulários online estarão disponíveis quando um serviço de entrega verificado for conectado.", instagram: "Instagram oficial" }; const instagram = business.socialProfiles.value?.find((profile) => profile.platform === "instagram" && profile.verified); return <><PageHero {...page} /><Section><div className="container contact-layout"><div className="contact-details"><p className="eyebrow">{text.contact}</p><h2>{text.title}</h2><a href={`tel:${phone.replace(/[^+\d]/g, "")}`}>{phone}</a><a href={`mailto:${email}`}>{email}</a><p><strong>{text.address}</strong><br />{business.mailingAddress.value}</p>{instagram && <a href={instagram.url} rel="noopener noreferrer" target="_blank">{text.instagram} ↗</a>}</div><aside className="contact-action-card"><p className="eyebrow">{text.help}</p><h2>{text.helpTitle}</h2><p>{text.helpText}</p><div><a className="button button-gold" href={`tel:${phone.replace(/[^+\d]/g, "")}`}>{text.call} <span aria-hidden="true">→</span></a><a className="button button-outline" href={`mailto:${email}`}>{text.email} <span aria-hidden="true">→</span></a></div><small>{text.note}</small></aside></div></Section></>; }

function LocalizedBook({ locale }: { locale: Locale }) { const page = copy[locale].pages.book; const text = locale === "es" ? { eyebrow: "Antes de empezar", title: "Ten estos detalles cerca.", list: ["Recogida y destino", "Fecha y hora de viaje preferida", "Detalles de pasajeros y equipaje", "Información de vuelo, crucero o varias paradas"], box: "Reserva segura", boxTitle: "Continúa a la experiencia de reserva de Revival.", boxText: "El enlace de reserva abre en una nueva pestaña. Los parámetros de campaña se conservan cuando la plataforma externa los admite; no se agregan datos personales a la URL.", button: "Continuar a la reserva", call: "¿Prefieres llamar?" } : { eyebrow: "Antes de começar", title: "Tenha estes detalhes por perto.", list: ["Local de partida e destino", "Data e horário preferido", "Detalhes de passageiros e bagagens", "Informações de voo, cruzeiro ou várias paradas"], box: "Reserva segura", boxTitle: "Continue para a experiência de reserva da Revival.", boxText: "O link de reserva abre em uma nova aba. Parâmetros de campanha são preservados quando a plataforma externa oferece suporte; dados pessoais não são adicionados à URL.", button: "Continuar para a reserva", call: "Prefere ligar?" }; const phone = business.phone.value ?? ""; return <><PageHero {...page} /><Section><div className="container booking-layout"><div><SectionHeading eyebrow={text.eyebrow} title={text.title} /><ul className="check-list">{text.list.map((item) => <li key={item}><span>✓</span>{item}</li>)}</ul></div><div className="booking-box"><p className="eyebrow">{text.box}</p><h2>{text.boxTitle}</h2><p>{text.boxText}</p><BookingLink className="button button-gold button-full" placement="book-page">{text.button} <span aria-hidden="true">↗</span></BookingLink><a className="text-link" href={`tel:${phone.replace(/[^+\d]/g, "")}`}>{text.call} {phone} <span aria-hidden="true">→</span></a></div></div></Section></>; }

function LocalizedFaq({ locale }: { locale: Locale }) { const page = copy[locale].pages.faq; const items = getLocalizedSiteFaq(locale); return <><JsonLd data={faqSchema(items)} /><PageHero {...page} /><Section><div className="container narrow-content"><FaqList items={items} /></div></Section></>; }

function LocalizedInsights({ locale }: { locale: Locale }) { const page = copy[locale].pages.insights; const text = locale === "es" ? [["Planea las recogidas al aeropuerto", "Comparte el vuelo, la hora de recogida y el destino final para que el plan pueda revisarse con el contexto adecuado."], ["Organiza el día de crucero", "Incluye el horario del crucero, la terminal y el equipaje al solicitar una conexión privada con Port Canaveral."], ["Prepara un itinerario ejecutivo", "Para reuniones o varias paradas, comparte las ubicaciones y horarios desde el inicio."]] : [["Planeje a partida para o aeroporto", "Compartilhe voo, horário de partida e destino final para que o plano seja analisado com o contexto certo."], ["Organize o dia do cruzeiro", "Inclua horário do cruzeiro, terminal e bagagens ao solicitar uma conexão privativa com Port Canaveral."], ["Prepare um roteiro executivo", "Para reuniões ou várias paradas, compartilhe locais e horários desde o início."]]; const link = locale === "es" ? "Pregunta por tu viaje" : "Pergunte sobre sua viagem"; return <><PageHero {...page} /><Section><div className="container insight-grid">{text.map(([title, description], index) => <article className="insight-card" key={title}><span>0{index + 1}</span><h2>{title}</h2><p>{description}</p><Link className="text-link" href={href(locale, "/contact")}>{link} <i aria-hidden="true">→</i></Link></article>)}</div></Section></>; }

function LocalizedReviews({ locale }: { locale: Locale }) { const page = copy[locale].pages.reviews; const text = locale === "es" ? { eyebrow: "Reseñas de Google", title: "Consulta los comentarios públicos más recientes.", body: "Para conservar la precisión, esta página no repite testimonios anónimos ni desactualizados. Usa el enlace para consultar la información actual disponible en Google.", open: "Abrir reseñas de Google" } : { eyebrow: "Avaliações do Google", title: "Veja os comentários públicos mais recentes.", body: "Para manter a precisão, esta página não repete depoimentos anônimos ou desatualizados. Use o link para ver as informações atuais disponíveis no Google.", open: "Abrir avaliações do Google" }; return <><PageHero {...page} /><Section><div className="container review-source"><p className="eyebrow">{text.eyebrow}</p><h2>{text.title}</h2><p>{text.body}</p><a className="button button-dark" href={`https://www.google.com/maps/search/?api=1&query_place_id=${business.googlePlaceId.value}&query=Revival%20Transportation%20Group`} rel="noreferrer" target="_blank">{text.open} <span aria-hidden="true">↗</span></a></div></Section></>; }

function LocalizedLegal({ locale, page }: { locale: Locale; page: "privacy-policy" | "terms-of-service" | "ride-terms" | "accessibility" }) { const pageCopy = copy[locale].pages[page]; const content = legalCopy[locale][page]; return <><PageHero {...pageCopy} /><Section><article className="container legal-content">{content.map(([heading, body]) => <div key={heading}><h2>{heading}</h2><p>{body}</p></div>)}</article></Section></>; }

