export function localizedPageMetadata(locale: Locale, segments: string[]) {
  const path = segments.join("/");
  if (!path) return { title: locale === "es" ? "Transporte privado en Florida Central" : "Transporte privativo na Flórida Central", description: copy[locale].home.intro, path: "/" };
  if (segments[0] === "services" && segments[1]) { const service = getLocalizedService(locale, segments[1]); return service ? { title: service.seoTitle, description: service.seoDescription, path: `/services/${service.slug}` } : undefined; }
  if (segments[0] === "routes" && segments[1]) { const route = getLocalizedRoute(locale, segments[1]); return route ? { title: route.seoTitle, description: route.seoDescription, path: `/routes/${route.slug}` } : undefined; }
  if (segments[0] === "airports" && segments[1]) { const airport = getLocalizedAirports(locale).find((item) => item.slug === segments[1]); return airport ? { title: airport.seoTitle, description: airport.seoDescription, path: `/airports/${airport.slug}` } : undefined; }
  const page = copy[locale].pages[path]; return page ? { title: page.title, description: page.intro, path: `/${path}` } : undefined;
}
